//! The Orthogonal oscillator's sample library (generated by
//! tools/gen-ortholib.py), embedded in the plugin as FLAC: 57 sets of three
//! recordings (C2, C3, C4 in Bitwig's naming, i.e. MIDI 48, 60, 72), each four bars at 98 BPM.
//! Nothing is decoded until a set is chosen (ortho::bank), so the plugin
//! loads as fast as before; the panel draws each set from its overview.

/// One recording: where its FLAC stream is in `DATA`, how many frames it
/// decodes to, and the gain that brings its held part to the library's level.
pub struct Rec {
    pub start: u32,
    pub bytes: u32,
    pub frames: u32,
    pub gain: f32,
}

/// A set: its name (as the menus show it), category (CATEGORIES), length in
/// frames (its longest recording), its three recordings (L, M, H) and its
/// middle recording's peaks, column by column over its length (0..255).
pub struct SetInfo {
    pub name: &'static str,
    pub category: usize,
    pub frames: u32,
    pub recs: [Rec; 3],
    pub overview: [u8; OVERVIEW],
}

include!("ortholib_index.rs");

static DATA: &[u8] = include_bytes!("ortholib.bin");

/// The recordings' root notes (MIDI), L, M and H.
pub const ROOTS: [u8; 3] = [48, 60, 72];

/// The held part of every recording, and how long a held note's Speed plays
/// into it before waiting for the release (seconds).
pub const HOLD_S: f32 = 4.5;

/// Recording `rec` (0 L, 1 M, 2 H) of set `set`, decoded, at its gain.
pub fn decode(set: usize, rec: usize) -> Vec<f32> {
    let info = &SETS[set].recs[rec];
    let stream = &DATA[info.start as usize..(info.start + info.bytes) as usize];
    let mut reader = claxon::FlacReader::new(stream).expect("an Orthogonal sample's FLAC stream");
    let scale = info.gain / 32767.0;
    let mut out = Vec::with_capacity(info.frames as usize);
    out.extend(reader.samples().map(|s| s.expect("a FLAC sample") as f32 * scale));
    out
}

/// Which recording a note at `hz` plays: the middle one from G (MIDI 55)
/// through F# (66) around its root, the low one below, the high one above.
pub fn recording_for(hz: f32) -> usize {
    let semis = 12.0 * (hz / crate::engine::note_freq(ROOTS[0])).log2();
    if semis < 6.5 { 0 } else if semis < 18.5 { 1 } else { 2 }
}

/// The set names of one category, with their indices (for the picker).
pub fn category(c: usize) -> impl Iterator<Item = (usize, &'static str)> {
    SETS.iter().enumerate().filter(move |(_, s)| s.category == c).map(|(k, s)| (k, s.name))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn library_is_present_and_decodes() {
        assert_eq!(SETS.len(), 57);
        let end = SETS.iter().flat_map(|s| s.recs.iter()).map(|r| r.start + r.bytes).max().unwrap();
        assert_eq!(end as usize, DATA.len());
        for set in [0, 30, SETS.len() - 1] {
            for rec in 0..3 {
                let x = decode(set, rec);
                assert_eq!(x.len(), SETS[set].recs[rec].frames as usize);
                assert!(x.len() <= SETS[set].frames as usize);
                // Every recording's held part is at the library's level, -18 dB RMS.
                let held = &x[..(2.0 * 4.0 * 60.0 / 98.0 * RATE) as usize];
                let rms = (held.iter().map(|v| v * v).sum::<f32>() / held.len() as f32).sqrt();
                assert!((20.0 * rms.log10() + 18.0).abs() < 0.1, "set {set} rec {rec}: {rms}");
            }
        }
        // Grouped by category, in menu order.
        assert!(SETS.windows(2).all(|w| w[0].category <= w[1].category));
        assert_eq!(category(0).count() + category(1).count() + category(2).count() + category(3).count(), SETS.len());
    }

    #[test]
    fn notes_pick_their_recording() {
        use crate::engine::note_freq;
        assert_eq!(recording_for(note_freq(54)), 0);
        assert_eq!(recording_for(note_freq(55)), 1);
        assert_eq!(recording_for(note_freq(66)), 1);
        assert_eq!(recording_for(note_freq(67)), 2);
        assert_eq!(recording_for(note_freq(20)), 0);
        assert_eq!(recording_for(note_freq(110)), 2);
    }
}
